#pragma once

#include <cstdint>

// Controller button glyphs shipped as RGBA8 PNGs under assets/glyphs/<style>/<button>.png
// (generated by tools/gen_glyphs.py, copied next to sunshine.exe at build time).

enum class GlyphStyle : uint8_t {
    Xbox,
    PlayStation,
    Switch,
    GameCube,
    Keyboard,
    Count,
};

enum class PadButton : uint8_t {
    A,
    B,
    X,
    Y,
    Z,
    Start,
    L,
    R,
    DpadUp,
    DpadDown,
    DpadLeft,
    DpadRight,
    CUp,
    CDown,
    CLeft,
    CRight,
    StickL,
    StickR,
    Count,
};

struct GlyphImage {
    uint32_t width;
    uint32_t height;
    const uint8_t* rgba; // width * height * 4 bytes, row-major, top row first
};

extern GlyphStyle g_glyphStyle;

void glyphsSetStyle(GlyphStyle style);

// Returns nullptr if the PNG is missing or cannot be decoded; callers keep their original art.
const GlyphImage* glyphFor(GlyphStyle style, PadButton button);
